"use strict";(function(){const FRAME_SELECTOR=[".gstore-hb-v1 .hb-cover",".gstore-hb-v1 .hb-thumb",".Gstore-home-blog__image",".Gstore-blog-card__image",".Gstore-blog-recent-post__image",".Gstore-blog-single-image",".Gstore-blog-single-related__image"].join(",");function cssUrl(url){return'url("'+String(url).replace(/\\/g,"\\\\").replace(/"/g,'\\"')+'")'}function getImageUrl(img){return img.currentSrc||img.src||img.getAttribute("src")||img.getAttribute("data-src")||""}function applyFrame(frame){const img=frame.querySelector("img");const imageUrl=img?getImageUrl(img):"";if(!imageUrl){frame.style.removeProperty("--gstore-blog-image-bg");frame.classList.remove("has-blog-image-bg");if(img&&!img.dataset.gstoreBlogFitBound){img.dataset.gstoreBlogFitBound="1";img.addEventListener("load",function(){applyFrame(frame)},{once:true})}return}frame.style.setProperty("--gstore-blog-image-bg",cssUrl(imageUrl));frame.classList.add("has-blog-image-bg")}function init(root){const scope=root||document;if(scope.matches&&scope.matches(FRAME_SELECTOR)){applyFrame(scope)}scope.querySelectorAll(FRAME_SELECTOR).forEach(applyFrame)}function observeChanges(){const observer=new MutationObserver(function(mutations){mutations.forEach(function(mutation){mutation.addedNodes.forEach(function(node){if(node.nodeType===1){init(node)}})})});observer.observe(document.body,{childList:true,subtree:true})}function start(){init(document);observeChanges()}if(document.readyState==="loading"){document.addEventListener("DOMContentLoaded",start)}else{start()}})();
